import{_ as t,o as e,c as a,Q as d}from"./chunks/framework.48927342.js";const u=JSON.parse('{"title":"Dinner Invitation","description":"","frontmatter":{},"headers":[],"relativePath":"en/more/maltese/practice/emails/05-dinner-invitation.md","filePath":"en/more/maltese/practice/emails/05-dinner-invitation.md"}'),r={name:"en/more/maltese/practice/emails/05-dinner-invitation.md"},n=d('<h1 id="dinner-invitation" tabindex="-1">Dinner Invitation <a class="header-anchor" href="#dinner-invitation" aria-label="Permalink to &quot;Dinner Invitation&quot;">​</a></h1><p><strong>Scenario:</strong> Anna invites her friend Mark to dinner at her home.</p><h2 id="email-header" tabindex="-1">Email Header <a class="header-anchor" href="#email-header" aria-label="Permalink to &quot;Email Header&quot;">​</a></h2><p><strong>Lil (To):</strong> <a href="mailto:mark.b@gmail.com" target="_blank" rel="noreferrer">mark.b@gmail.com</a><strong>Mingħand (From):</strong> <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a><strong>Data (Date):</strong> 12 ta&#39; Ottubru 2026 <strong>Suġġett (Subject):</strong> Stedina għall-ikla ta&#39; filgħaxija</p><h2 id="full-email" tabindex="-1">Full Email <a class="header-anchor" href="#full-email" aria-label="Permalink to &quot;Full Email&quot;">​</a></h2><blockquote><p><strong>Lil:</strong> <a href="mailto:mark.b@gmail.com" target="_blank" rel="noreferrer">mark.b@gmail.com</a><strong>Mingħand:</strong> <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a><strong>Data:</strong> 12 ta&#39; Ottubru 2026 <strong>Suġġett:</strong> Stedina għall-ikla ta&#39; filgħaxija</p><p>Għażiż Mark,</p><p>Nispera li inti tajjeb.</p><p>Nixtieq nistednek għall-ikla ta&#39; filgħaxija d-dar tiegħi nhar il-Ġimgħa.</p><p>Se nibdew fis-sebgħa ta&#39; filgħaxija.</p><p>Se nkunu ftit ħbieb u nieklu flimkien.</p><p>Se nipprepara platt Malti u deżerta.</p><p>Jekk jogħġbok, għidli jekk għandek xi preferenzi għall-ikel.</p><p>Nispera li tkun tista&#39; tiġi.</p><p>Tislijiet, Anna</p></blockquote><h2 id="sentence-by-sentence-translation-and-word-notes" tabindex="-1">Sentence-by-Sentence Translation and Word Notes <a class="header-anchor" href="#sentence-by-sentence-translation-and-word-notes" aria-label="Permalink to &quot;Sentence-by-Sentence Translation and Word Notes&quot;">​</a></h2><p><strong>Malti:</strong> Lil: <a href="mailto:mark.b@gmail.com" target="_blank" rel="noreferrer">mark.b@gmail.com</a></p><p><strong>Translation:</strong> To: <a href="mailto:mark.b@gmail.com" target="_blank" rel="noreferrer">mark.b@gmail.com</a></p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Lil</td><td>to; recipient</td><td>Maltese label for the email &quot;To&quot; field</td></tr><tr><td><a href="mailto:mark.b@gmail.com" target="_blank" rel="noreferrer">mark.b@gmail.com</a></td><td>email address</td><td>Recipient&#39;s (Mark&#39;s) email</td></tr></tbody></table><p><strong>Malti:</strong> Mingħand: <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a></p><p><strong>Translation:</strong> From: <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a></p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Mingħand</td><td>from; sender</td><td>Maltese label for the email &quot;From&quot; field; literally &quot;from ...&quot;</td></tr><tr><td><a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a></td><td>email address</td><td>Sender&#39;s (Anna&#39;s) email</td></tr></tbody></table><p><strong>Malti:</strong> Data: 12 ta&#39; Ottubru 2026</p><p><strong>Translation:</strong> Date: 12 October 2026</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Data</td><td>date</td><td>Email &quot;Date&quot; field; Maltese date format is &quot;day ta&#39; month year&quot;</td></tr><tr><td>12</td><td>twelve</td><td>Day in the date</td></tr><tr><td>ta&#39;</td><td>of</td><td>Links the day and the month</td></tr><tr><td>Ottubru</td><td>October</td><td>Month name</td></tr></tbody></table><p><strong>Malti:</strong> Suġġett: Stedina għall-ikla ta&#39; filgħaxija</p><p><strong>Translation:</strong> Subject: Dinner Invitation</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Suġġett</td><td>subject</td><td>Email &quot;Subject&quot; field</td></tr><tr><td>Stedina</td><td>invitation</td><td>Feminine noun</td></tr><tr><td>għall-ikla</td><td>to the meal</td><td>Contracted <code>għal</code> + <code>l-ikla</code></td></tr><tr><td>ta&#39;</td><td>of; during</td><td>Links the noun and time expression</td></tr><tr><td>filgħaxija</td><td>in the evening</td><td>Time expression</td></tr></tbody></table><p><strong>Malti:</strong> Għażiż Mark,</p><p><strong>Translation:</strong> Dear Mark,</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Għażiż</td><td>dear</td><td>Masculine singular form of address</td></tr><tr><td>Mark</td><td>Mark</td><td>Name</td></tr></tbody></table><h3 id="_1" tabindex="-1">1. <a class="header-anchor" href="#_1" aria-label="Permalink to &quot;1.&quot;">​</a></h3><p><strong>Malti:</strong> Nispera li inti tajjeb.</p><p><strong>Translation:</strong> I hope you are well.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Nispera</td><td>I hope</td><td>First-person singular form</td></tr><tr><td>li</td><td>that; introduces a clause</td><td>Conjunction</td></tr><tr><td>inti</td><td>you</td><td>Second-person singular pronoun</td></tr><tr><td>tajjeb</td><td>well; good</td><td>Masculine form; feminine form is <code>tajba</code></td></tr></tbody></table><h3 id="_2" tabindex="-1">2. <a class="header-anchor" href="#_2" aria-label="Permalink to &quot;2.&quot;">​</a></h3><p><strong>Malti:</strong> Nixtieq nistednek għall-ikla ta&#39; filgħaxija d-dar tiegħi nhar il-Ġimgħa.</p><p><strong>Translation:</strong> I would like to invite you to dinner at my home on Friday evening.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Nixtieq</td><td>I would like; I wish</td><td>Polite expression of a wish</td></tr><tr><td>nistednek</td><td>I invite you</td><td>First-person form of the invitation verb with a second-person singular object suffix</td></tr><tr><td>għall-ikla</td><td>to the meal; for dinner</td><td><code>għal</code> + definite article <code>l-</code> contracts with <code>ikla</code></td></tr><tr><td>ta&#39;</td><td>of; during</td><td>Links the noun and time expression</td></tr><tr><td>filgħaxija</td><td>in the evening</td><td>Time expression</td></tr><tr><td>d-dar</td><td>at home; the house</td><td>Common contracted spelling of <code>id-dar</code></td></tr><tr><td>tiegħi</td><td>my; mine</td><td>First-person singular possessive</td></tr><tr><td>nhar</td><td>on the day of</td><td>Introduces a weekday or date</td></tr><tr><td>il-Ġimgħa</td><td>Friday</td><td>Weekday commonly used with the definite article</td></tr></tbody></table><h3 id="_3" tabindex="-1">3. <a class="header-anchor" href="#_3" aria-label="Permalink to &quot;3.&quot;">​</a></h3><p><strong>Malti:</strong> Se nibdew fis-sebgħa ta&#39; filgħaxija.</p><p><strong>Translation:</strong> We will start at seven in the evening.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Se</td><td>will; going to</td><td>Future marker</td></tr><tr><td>nibdew</td><td>we start</td><td>First-person plural form</td></tr><tr><td>fis-sebgħa</td><td>at seven</td><td><code>f&#39;</code> contracts with the definite clock-hour form</td></tr><tr><td>ta&#39;</td><td>of; during</td><td>Links the hour and time of day</td></tr><tr><td>filgħaxija</td><td>in the evening</td><td>Time expression</td></tr></tbody></table><h3 id="_4" tabindex="-1">4. <a class="header-anchor" href="#_4" aria-label="Permalink to &quot;4.&quot;">​</a></h3><p><strong>Malti:</strong> Se nkunu ftit ħbieb u nieklu flimkien.</p><p><strong>Translation:</strong> A few friends will be there, and we will eat together.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Se</td><td>will</td><td>Future marker</td></tr><tr><td>nkunu</td><td>we will be</td><td>First-person plural form of <code>ikun</code></td></tr><tr><td>ftit</td><td>a few; a little</td><td>Quantifier</td></tr><tr><td>ħbieb</td><td>friends</td><td>Plural of <code>ħabib</code></td></tr><tr><td>u</td><td>and</td><td>Conjunction</td></tr><tr><td>nieklu</td><td>we eat</td><td>First-person plural form</td></tr><tr><td>flimkien</td><td>together</td><td>Adverb</td></tr></tbody></table><h3 id="_5" tabindex="-1">5. <a class="header-anchor" href="#_5" aria-label="Permalink to &quot;5.&quot;">​</a></h3><p><strong>Malti:</strong> Se nipprepara platt Malti u deżerta.</p><p><strong>Translation:</strong> I will prepare a Maltese dish and dessert.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Se</td><td>will</td><td>Future marker</td></tr><tr><td>nipprepara</td><td>I prepare</td><td>First-person singular form</td></tr><tr><td>platt</td><td>dish; plate</td><td>Masculine noun; means &quot;dish&quot; here</td></tr><tr><td>Malti</td><td>Maltese-style</td><td>Masculine singular form agreeing with <code>platt</code></td></tr><tr><td>u</td><td>and</td><td>Conjunction</td></tr><tr><td>deżerta</td><td>dessert</td><td>Feminine noun</td></tr></tbody></table><h3 id="_6" tabindex="-1">6. <a class="header-anchor" href="#_6" aria-label="Permalink to &quot;6.&quot;">​</a></h3><p><strong>Malti:</strong> Jekk jogħġbok, għidli jekk għandek xi preferenzi għall-ikel.</p><p><strong>Translation:</strong> Please tell me if you have any food preferences.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Jekk jogħġbok</td><td>please</td><td>Fixed polite expression</td></tr><tr><td>għidli</td><td>tell me</td><td><code>għid</code> &quot;tell&quot; + <code>-li</code> &quot;me&quot;</td></tr><tr><td>jekk</td><td>whether; if</td><td>Introduces an indirect question here</td></tr><tr><td>għandek</td><td>you have</td><td>Second-person singular form of <code>għand</code></td></tr><tr><td>xi</td><td>some; any</td><td>Indefinite determiner</td></tr><tr><td>preferenzi</td><td>preferences</td><td>Plural of <code>preferenza</code></td></tr><tr><td>għall-ikel</td><td>for food; regarding food</td><td><code>għal</code> contracts with the definite article before <code>ikel</code></td></tr></tbody></table><h3 id="_7" tabindex="-1">7. <a class="header-anchor" href="#_7" aria-label="Permalink to &quot;7.&quot;">​</a></h3><p><strong>Malti:</strong> Nispera li tkun tista&#39; tiġi.</p><p><strong>Translation:</strong> I hope you will be able to come.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Nispera</td><td>I hope</td><td>First-person singular form</td></tr><tr><td>li</td><td>that; introduces a clause</td><td>Conjunction</td></tr><tr><td>tkun</td><td>you will be; you may be</td><td>Second-person/subordinate form of <code>ikun</code></td></tr><tr><td>tista&#39;</td><td>you can</td><td>Second-person singular form</td></tr><tr><td>tiġi</td><td>you come</td><td>Second-person singular form</td></tr></tbody></table><p><strong>Malti:</strong> Tislijiet, Anna</p><p><strong>Translation:</strong> Regards, Anna (email closing).</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Tislijiet</td><td>regards; best wishes</td><td>Formal email/letter closing, literally &quot;greetings/regards&quot;</td></tr><tr><td>Anna</td><td>Anna</td><td>Name</td></tr></tbody></table>',53),i=[n];function o(l,s,h,g,m,c){return e(),a("div",null,i)}const b=t(r,[["render",o]]);export{u as __pageData,b as default};
